#!/usr/bin/env node
'use strict';
/*
 * gen-psl.js - build-time tool (run by a developer, never by the extension): turns publicsuffix.org's
 * public_suffix_list.dat into the compact bundled copy extension/core/psl-data.js.
 *
 *   node scripts/gen-psl.js --fetch            download https://publicsuffix.org/list/public_suffix_list.dat once and generate
 *   node scripts/gen-psl.js path/to/list.dat   generate from a copy you already have
 *
 * The extension itself never downloads the list: the generated file is committed and ships inside the package.
 * Both the ICANN and the PRIVATE sections are kept (so a.github.io and b.github.io are different owners).
 * Rules are converted to punycode (what URL.hostname gives) and grouped by their last label to keep the file small.
 * The list is published under the Mozilla Public License 2.0; the notice is repeated in the generated file.
 */
const fs = require('node:fs');
const path = require('node:path');
const { domainToASCII } = require('node:url');

const OUT = path.join(__dirname, '..', 'extension', 'core', 'psl-data.js');

function toAscii(rule) { // keeps the leading "!" / "*." markers, converts the rest
  const m = /^(!|\*\.)?(.+)$/.exec(rule);
  const body = domainToASCII(m[2]);
  if (!body) throw new Error('cannot convert rule: ' + rule);
  return (m[1] || '') + body;
}

function parse(text) {
  const rules = [];
  let version = '', commit = '';
  for (const raw of text.split(/\r?\n/)) {
    const v = /^\/\/ VERSION: (.+)$/.exec(raw); if (v) version = v[1].trim();
    const c = /^\/\/ COMMIT: (.+)$/.exec(raw); if (c) commit = c[1].trim();
    const line = raw.trim();
    if (!line || line.startsWith('//')) continue;
    rules.push(toAscii(line.split(/\s+/)[0].toLowerCase()));
  }
  return { rules, version, commit };
}

// "uk" group: "uk co org.sch" would be ambiguous with the markers, so every line is: tld<TAB>entry entry ...
// where an entry is the rule with ".tld" removed ("" for the bare tld is written "@"), keeping a leading "!" or "*." marker.
function pack(rules) {
  const groups = new Map();
  for (const r of rules) {
    const mark = r.startsWith('!') ? '!' : r.startsWith('*.') ? '*.' : '';
    const body = r.slice(mark.length);
    const i = body.lastIndexOf('.');
    const tld = i < 0 ? body : body.slice(i + 1);
    const rest = i < 0 ? '@' : body.slice(0, i);
    if (!groups.has(tld)) groups.set(tld, []);
    groups.get(tld).push(mark + rest);
  }
  return [...groups.keys()].sort().map((t) => t + '\t' + groups.get(t).join(' ')).join('\n');
}

async function main() {
  const arg = process.argv[2];
  if (!arg) { console.error('usage: node scripts/gen-psl.js --fetch | <public_suffix_list.dat>'); process.exit(2); }
  let text;
  if (arg === '--fetch') {
    const res = await fetch('https://publicsuffix.org/list/public_suffix_list.dat');
    if (!res.ok) throw new Error('download failed: HTTP ' + res.status);
    text = await res.text();
  } else text = fs.readFileSync(arg, 'utf8');
  const { rules, version, commit } = parse(text);
  if (rules.length < 5000) throw new Error('suspiciously short list (' + rules.length + ' rules)');
  const packed = pack(rules);
  const out = `/*
 * psl-data.js - GENERATED by scripts/gen-psl.js. Do not edit by hand.
 * A fixed, bundled copy of the Public Suffix List (ICANN + private sections) from https://publicsuffix.org/list/public_suffix_list.dat
 * VERSION ${version}  COMMIT ${commit}  ${rules.length} rules.
 * The extension never downloads this list; to update it, run the script and commit the result.
 * The Public Suffix List is Copyright its contributors and is licensed under the Mozilla Public License 2.0
 * (https://mozilla.org/MPL/2.0/), see https://publicsuffix.org/.
 * Format: one line per last label: <tld><TAB><entries separated by spaces>. An entry is the rule without ".<tld>"
 * ("@" is the bare tld itself); a leading "!" marks an exception rule and "*." a wildcard rule.
 */
(function (root, factory) {
  var api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  else root.TCPslData = api;
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';
  return { version: ${JSON.stringify(version)}, commit: ${JSON.stringify(commit)}, count: ${rules.length}, packed: ${JSON.stringify(packed)} };
});
`;
  fs.writeFileSync(OUT, out);
  console.log('wrote ' + path.relative(process.cwd(), OUT) + ' (' + rules.length + ' rules, ' + out.length + ' bytes, list version ' + version + ')');
}
if (require.main === module) main().catch((e) => { console.error(e.message); process.exit(1); });
module.exports = { parse, pack };
